import { formatDate, formatMoney, StatusBadge } from "../rfq/RfqUi";

export default function VendorQuotes({ quotes }) {
  return <section><p className="marketplace-eyebrow">Quotation activity</p><h2 className="mt-2 text-3xl font-bold">My Quotations</h2><p className="mt-3 text-sm text-slate-600">Track the commercial responses submitted from this supplier account.</p><div className="mt-7 grid gap-4 lg:grid-cols-2">{!quotes.length ? <div className="rounded-2xl border border-dashed border-slate-300 bg-white p-12 text-center text-sm text-slate-600 lg:col-span-2">No quotations submitted yet.</div> : quotes.map((quote) => <article key={quote.id} className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><div className="flex items-start justify-between gap-4"><div><p className="text-xs font-bold uppercase tracking-wider text-orange-700">Requirement</p><h3 className="mt-1 font-bold">{quote.rfq?.title || `RFQ #${quote.rfqId}`}</h3></div><StatusBadge status={quote.status}/></div><dl className="mt-4 grid grid-cols-2 gap-3 text-sm"><div className="rounded-xl bg-slate-50 p-3"><dt className="text-xs text-slate-500">Quoted price</dt><dd className="mt-1 font-bold">{formatMoney(quote.price)}</dd></div><div className="rounded-xl bg-slate-50 p-3"><dt className="text-xs text-slate-500">Submitted</dt><dd className="mt-1 font-bold">{formatDate(quote.createdAt) || "—"}</dd></div></dl>{quote.message && <p className="mt-4 whitespace-pre-wrap text-sm leading-6 text-slate-600">{quote.message}</p>}</article>)}</div></section>;
}
